// Which week to report on: the webhook can name one; the Monday schedule reports on last week.
const body = $input.first().json.body; // undefined when the schedule started the run
let weekStart = body ? body.week_start : null;
if (!weekStart) {
  const dubaiNow = new Date(Date.now() + 4 * 3600 * 1000); // Dubai is UTC+4 all year (no daylight saving)
  const daysSinceMonday = (dubaiNow.getUTCDay() + 6) % 7;
  const thisMonday = Date.UTC(dubaiNow.getUTCFullYear(), dubaiNow.getUTCMonth(), dubaiNow.getUTCDate() - daysSinceMonday);
  weekStart = new Date(thisMonday - 7 * 86400000).toISOString().slice(0, 10);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(weekStart))) throw new Error(`week_start ${weekStart} is not YYYY-MM-DD`);
if (new Date(`${weekStart}T00:00:00Z`).getUTCDay() !== 1) throw new Error(`week_start ${weekStart} is not a Monday`);
return [{ json: { week_start: weekStart, from_webhook: Boolean(body), step: 'read_data', dedupe_text: `${(body && body.run_tag) || ''}|${weekStart}` } }];

// Idempotency: the same input twice must not create two records.
// Keys live in this workflow's static data (n8n saves it after production runs, not manual test runs).
const item = $input.first().json;
const key = item.dedupe_key || item.dedupe_text;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = Boolean(store.seen[key]);
if (!duplicate) store.seen[key] = new Date().toISOString();
const json = { ...item, dedupe_key: key, is_duplicate: duplicate };
const binary = undefined; // invoices carry the uploaded file along
return [binary ? { json, binary } : { json }];

// Every number in the report is computed here, in code. The AI never does arithmetic.
// Rounding uses integer maths so the result is identical to the Python reference.
const PRIORITIES = ["P1", "P2", "P3", "P4"];
const TEAMS = ["Technical", "Billing", "Delivery", "Product", "Account"];
const CATEGORIES = ["sales", "support", "complaint", "partnership", "spam"];
const SLA_MINUTES = {"P1": 60, "P2": 240, "P3": 1440, "P4": 2880};
const cfg = $('Config').first().json;
const week = $('Seen before?').first().json;
const tickets = $('Parse tickets CSV').all().map((i) => i.json);
const enquiries = $('Parse enquiries CSV').all().map((i) => i.json);

const addDays = (iso, n) => new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86400000).toISOString().slice(0, 10);
const pct = (part, whole) => (whole === 0 ? 0 : Math.floor((2000 * part + whole) / (2 * whole)) / 10);
const avg1 = (total, count) => (count === 0 ? 0 : Math.floor((20 * total + count) / (2 * count)) / 10);
const changePct = (cur, prev) => (prev === 0 ? null : (cur < prev ? -1 : 1) * pct(Math.abs(cur - prev), prev));
// Timestamps are stored in Dubai local time (+04:00), so the first 10 characters are the local date.
const inWeek = (ts, start, end) => start <= String(ts).slice(0, 10) && String(ts).slice(0, 10) <= end;
const countBy = (rows, field, keys) => Object.fromEntries(keys.map((k) => [k, rows.filter((r) => r[field] === k).length]));

const start = week.week_start;
const end = addDays(start, 6);
const current = tickets.filter((t) => inWeek(t.created_at, start, end));
const previousCount = tickets.filter((t) => inWeek(t.created_at, addDays(start, -7), addDays(start, -1))).length;
const weekEnquiries = enquiries.filter((e) => inWeek(e.received_at, start, end));
const minutes = current.map((t) => Number(t.first_response_minutes));
const numbers = {
  week_start: start,
  week_end: end,
  tickets_total: current.length,
  tickets_prev_week: previousCount,
  tickets_change_pct: changePct(current.length, previousCount),
  tickets_by_priority: countBy(current, 'priority', PRIORITIES),
  tickets_by_team: countBy(current, 'team', TEAMS),
  negative_sentiment_pct: pct(current.filter((t) => t.sentiment === 'negative').length, current.length),
  avg_first_response_minutes: avg1(minutes.reduce((a, b) => a + b, 0), minutes.length),
  sla_breaches: current.filter((t) => Number(t.first_response_minutes) > SLA_MINUTES[t.priority]).length,
  enquiries_total: weekEnquiries.length,
  enquiries_by_category: countBy(weekEnquiries, 'category', CATEGORIES),
  spam_pct: pct(weekEnquiries.filter((e) => e.category === 'spam').length, weekEnquiries.length),
};
return [{
  json: {
    ...week,
    numbers,
    step: 'ai_narrative',
    llm_request: {
      model: cfg.model_main,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: cfg.prompt_narrative }, { role: 'user', content: JSON.stringify(numbers) }],
    },
  },
}];

// JSON-schema check of the model's reply. Invalid output is never used: it goes to human review.
// Parse the model's reply and check it against a JSON Schema (the subset our schemas use).
function parseJsonObject(text) {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const value = JSON.parse(text.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
  } catch (error) {
    return null;
  }
}
function isType(value, type) {
  if (type === 'null') return value === null;
  if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
  if (type === 'integer') return Number.isInteger(value);
  if (type === 'object') return value !== null && typeof value === 'object' && !Array.isArray(value);
  if (type === 'array') return Array.isArray(value);
  return typeof value === type;
}
function schemaErrors(value, schema, path = '$') {
  if (value === null && path === '$') return ['output is not a JSON object'];
  const types = [].concat(schema.type || []);
  if (types.length && !types.some((type) => isType(value, type))) return [`${path}: expected ${types.join(' or ')}`];
  const errors = [];
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${path}: must be one of ${JSON.stringify(schema.enum)}`);
  if (typeof value === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${path}: below ${schema.minimum}`);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${path}: above ${schema.maximum}`);
  }
  if (typeof value === 'string') {
    if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${path}: longer than ${schema.maxLength}`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errors.push(`${path}: does not match ${schema.pattern}`);
  }
  if (isType(value, 'object')) {
    const properties = schema.properties || {};
    for (const key of schema.required || []) if (!(key in value)) errors.push(`${path}.${key}: missing`);
    for (const [key, sub] of Object.entries(properties)) if (key in value) errors.push(...schemaErrors(value[key], sub, `${path}.${key}`));
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) if (!(key in properties)) errors.push(`${path}.${key}: not allowed`);
    }
  }
  return errors;
}
const SCHEMA = {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Weekly report narrative (numbers come from code, not from the model)", "type": "object", "required": ["headline", "narrative"], "additionalProperties": false, "properties": {"headline": {"type": "string", "maxLength": 160}, "narrative": {"type": "string", "maxLength": 2500}}};
const { llm_request, ...context } = $('Compute numbers (code)').first().json;
const content = $input.first().json.choices?.[0]?.message?.content || '';
const ai = parseJsonObject(content);
const errors = schemaErrors(ai, SCHEMA);
return [{ json: { ...context, ai: errors.length ? null : ai, schema_errors: errors } }];

// The AI never types a number. It writes placeholders such as {tickets_total} or {tickets_by_priority.P1};
// code fills them in from the computed numbers. If the AI typed a digit itself (other than the labels
// P1-P4) or used an unknown placeholder, the numbers still go out but the narrative is held for review.
const item = $input.first().json;
const numbers = item.numbers;
const PLACEHOLDER = /\{([a-z_]+(?:\.[A-Za-z0-9]+)?)\}/g;
const WITHHELD = "_Narrative withheld: it failed the checks (schema, placeholders or typed numbers). A human must review it._";

function lookup(path) {
  let value = numbers;
  for (const part of path.split('.')) {
    if (value === null || typeof value !== 'object' || !(part in value)) throw new Error(path);
    value = value[part];
  }
  if (value !== null && typeof value === 'object') throw new Error(path);
  return value;
}
// Python prints floats with one decimal and integers as they are; the JSON keeps that difference
// only through Number.isInteger, so the integer-valued metrics are listed explicitly.
const FLOAT_KEYS = ['tickets_change_pct', 'negative_sentiment_pct', 'avg_first_response_minutes', 'spam_pct'];
function formatValue(path, value) {
  if (value === null) return 'n/a';
  return FLOAT_KEYS.includes(path) ? Number(value).toFixed(1) : String(value);
}
// {tickets_change_pct} is signed: "fell by {tickets_change_pct}%" would print "fell by -22.4%".
const CHANGE_DOWN = new RegExp("\\b(?:fell|falls?|falling|down|decreased?|decreases|decreasing|drop|drops|dropped|declined?|declines|lower|eased|shrank)\\s+(?:(?:by|of)\\s+)?\\{tickets_change_pct\\}", 'i');
const CHANGE_UP = new RegExp("\\b(?:rose|rises?|rising|up|increased?|increases|increasing|grew|grows?|jumped|climbed|higher)\\s+(?:(?:by|of)\\s+)?\\{tickets_change_pct\\}", 'i');
function changeWordingProblems(text) {
  const change = numbers.tickets_change_pct;
  if (CHANGE_DOWN.test(text)) return ["a 'fell/down' word is placed before the signed {tickets_change_pct}"];
  if ((change === null || change === undefined || change < 0) && CHANGE_UP.test(text)) {
    return ["a 'rose/up' word is placed before {tickets_change_pct}, which is not an increase"];
  }
  return [];
}
function checkNarrative(text) {
  const problems = [];
  for (const match of text.matchAll(PLACEHOLDER)) {
    try { lookup(match[1]); } catch (unknown) { problems.push(`unknown placeholder {${match[1]}}`); }
  }
  const typed = text.replace(PLACEHOLDER, ' ').replace(/\bP[1-4]\b/g, ' ').match(/[0-9]+/g) || [];
  if (typed.length) problems.push(`AI typed numbers itself: ${typed.join(', ')}`);
  problems.push(...changeWordingProblems(text));
  if (problems.length) return { text, problems };
  return { text: text.replace(PLACEHOLDER, (m, path) => formatValue(path, lookup(path))), problems };
}

let problems = item.ai === null ? ['AI output failed the JSON schema check'] : [];
let headline = 'Weekly numbers (narrative held for review)';
let narrative = WITHHELD;
if (item.ai !== null) {
  const h = checkNarrative(item.ai.headline);
  const n = checkNarrative(item.ai.narrative);
  problems = [...h.problems, ...n.problems];
  if (!problems.length) { headline = h.text; narrative = n.text; }
}
const ok = problems.length === 0;
return [{ json: { ...item, status: ok ? 'sent' : 'needs_review', reason: problems.join('; '), headline, narrative } }];

// Render the "email" as Markdown and HTML: numbers table from code + narrative from the AI.
const cfg = $('Config').first().json;
const r = $input.first().json;
const n = r.numbers;
const one = (v) => Number(v).toFixed(1);
const rows = [
  ['Tickets this week', String(n.tickets_total)],
  ['Tickets last week', String(n.tickets_prev_week)],
  ['Change vs last week (%)', n.tickets_change_pct === null ? 'n/a' : one(n.tickets_change_pct)],
  ...Object.entries(n.tickets_by_priority).map(([p, c]) => [`${p} tickets`, String(c)]),
  ['SLA breaches (first response)', String(n.sla_breaches)],
  ['Negative sentiment (%)', one(n.negative_sentiment_pct)],
  ['Average first response (minutes)', one(n.avg_first_response_minutes)],
  ['Enquiries this week', String(n.enquiries_total)],
  ['Spam enquiries (%)', one(n.spam_pct)],
];
const escape = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#x27;');
const title = `Weekly operations report: ${n.week_start} to ${n.week_end}`;
const markdown = [
  `# ${title}`, '', `**${r.headline}**`, '', '| Metric | Value |', '|---|---|', ...rows.map(([k, v]) => `| ${k} | ${v} |`),
  '', '## Narrative (AI-written, numbers checked by code)', '', r.narrative.trim(), '',
].join('\n');
const bullets = r.narrative.split('\n').filter((l) => l.trim()).map((l) => `<li>${escape(l.replace(/^[-* ]+/, '').trim())}</li>`).join('');
const html = `<h1>${title}</h1><p><strong>${escape(r.headline)}</strong></p><table>${rows.map(([k, v]) => `<tr><td>${escape(k)}</td><td>${escape(v)}</td></tr>`).join('')}</table><ul>${bullets}</ul>`;
const dir = `${cfg.base_dir}/outputs/reports`;
return [
  { json: { ...r, target_path: `${dir}/weekly_${n.week_start}.md`, content: markdown } },
  { json: { ...r, target_path: `${dir}/weekly_${n.week_start}.html`, content: html } },
];

// The mock email outbox line (sent, or held for review) plus the shared review queue if needed.
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const SENT_COLUMNS = ["timestamp", "workflow", "item_id", "to", "subject", "status", "detail"];
const REVIEW_COLUMNS = ["timestamp", "workflow", "item_id", "reason", "details"];
const cfg = $('Config').first().json;
const r = $('Check narrative').first().json;
const now = new Date().toISOString();
const outbox = {
  timestamp: now, workflow: 'weekly_report', item_id: r.week_start, to: 'ops-managers@example.com',
  subject: `Weekly operations report ${r.week_start}`, status: r.status === 'sent' ? 'sent (mock)' : 'held for review',
  detail: `weekly_${r.week_start}.md`,
};
const rows = [{ target_path: `${cfg.base_dir}/outputs/sent_emails.csv`, line: csvRow(SENT_COLUMNS, outbox) }];
if (r.status === 'needs_review') {
  const review = { timestamp: now, workflow: 'weekly_report', item_id: r.week_start, reason: r.reason, details: null };
  rows.push({ target_path: `${cfg.base_dir}/outputs/human_review_queue.csv`, line: csvRow(REVIEW_COLUMNS, review) });
}
const response = { week_start: r.week_start, status: r.status, reason: r.reason, numbers: r.numbers };
return rows.map((row) => ({ json: { ...row, response, from_webhook: r.from_webhook } }));

// Error branch: write one row to logs/errors.csv, forget the idempotency key so the input
// can be retried later, and answer the webhook caller with status "error".
// CSV helpers: one line per record, quoted only when needed (same rule as Python's csv module).
function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\n\r]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function csvRow(columns, record) {
  return columns.map((column) => csvCell(record[column])).join(',') + '\n';
}
const COLUMNS = ["timestamp", "workflow", "item_id", "step", "error_type", "message"];
const cfg = $('Config').first().json;
const item = $input.first().json;
const error = item.error || 'unknown error';
const message = typeof error === 'string' ? error : error.description || error.message || JSON.stringify(error);
let itemId = 'unknown';
try {
  itemId = $('Webhook: run report').first().json.body.week_start || itemId; // straight from the trigger, in case the input check failed
} catch (noTrigger) {
  // started by the schedule, or no such field
}
try {
  const checked = $('Seen before?').first().json;
  itemId = checked.week_start || itemId;
  const key = checked.dedupe_key || checked.dedupe_text;
  const store = $getWorkflowStaticData('global');
  if (key && store.seen) delete store.seen[key];
} catch (notExecuted) {
  // the input check itself failed, so no key was stored yet
}
const record = {
  timestamp: new Date().toISOString(),
  workflow: 'weekly_report',
  item_id: itemId,
  step: item.step || 'check_input',
  error_type: typeof error === 'string' ? 'Error' : error.name || 'Error',
  message: String(message).slice(0, 500),
};
return [{
  json: {
    target_path: `${cfg.base_dir}/logs/errors.csv`,
    line: csvRow(COLUMNS, record),
    response: { status: 'error', item_id: itemId, step: record.step, reason: record.message },
  },
}];
